{"path":"workflow.py","content":""""Order reconciliation, v1 contract (see spec-v1.md).

Pure functions only: parses CSV strings, returns plain dicts with integer cents.
"""

import csv
import io
import json
from decimal import Decimal, InvalidOperation


def _parse_amount_cents(raw, context):
    """Parse a non-negative amount with at most 2 decimals into integer cents.

    Uses Decimal fixed-point (never float * 100). Raises ValueError on
    NaN/Infinity/negatives/>2 decimals/unparseable input.
    """
    if raw is None:
        raise ValueError("%s: missing amount" % context)
    text = str(raw).strip()
    if text == "":
        raise ValueError("%s: empty amount" % context)
    try:
        value = Decimal(text)
    except (InvalidOperation, ArithmeticError):
        raise ValueError("%s: invalid amount %r" % (context, raw))
    if not value.is_finite():
        raise ValueError("%s: non-finite amount %r" % (context, raw))
    if value < 0:
        raise ValueError("%s: negative amount %r" % (context, raw))
    sign, digits, exponent = value.as_tuple()
    if isinstance(exponent, int) and exponent < -2:
        raise ValueError("%s: more than two decimals %r" % (context, raw))
    cents = value.scaleb(2).to_integral_value()
    return int(cents)


def _read_rows(csv_text, required_header, kind):
    if csv_text is None:
        raise ValueError("%s csv is None" % kind)
    reader = csv.reader(io.StringIO(csv_text))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("%s csv is empty (missing header)" % kind)
    if header != required_header:
        raise ValueError(
            "%s csv bad header: expected %r, got %r" % (kind, required_header, header)
        )
    rows = []
    for row in rows_iter(reader):
        if len(row) != len(required_header):
            raise ValueError("%s csv bad row width: %r" % (kind, row))
        rows.append(tuple(row))
    return rows


def rows_iter(reader):
    # Skip fully blank lines; yield everything else.
    for row in reader:
        if row == []:
            continue
        yield row


def _dedupe(rows, id_index, kind):
    """Deduplicate rows by id. Identical rows collapse; conflicting rows raise."""
    seen = {}
    unique = []
    for row in rows:
        key = row[id_index]
        if key in seen:
            if seen[key] != row:
                raise ValueError(
                    "%s %s: duplicate id with differing fields: %r vs %r"
                    % (kind, key, seen[key], row)
                )
            continue
        seen[key] = row
        unique.append(row)
    return unique


def reconcile(orders_csv, refunds_csv, policy="v1", cutoff=None):
    if policy != "v1":
        raise ValueError("unsupported policy: %r" % (policy,))

    order_rows = _read_rows(orders_csv, ["order_id", "customer", "amount", "status", "created_at"], "orders")
    refund_rows = _read_rows(refunds_csv, ["refund_id", "order_id", "amount"], "refunds")

    order_rows = _dedupe(order_rows, 0, "order")
    refund_rows = _dedupe(refund_rows, 0, "refund")

    # Validate and index orders.
    orders = {}
    for order_id, customer, amount, status, _created_at in order_rows:
        if status not in ("paid", "cancelled"):
            raise ValueError("order %s: unknown status %r" % (order_id, status))
        cents = _parse_amount_cents(amount, "order %s" % order_id)
        orders[order_id] = {
            "order_id": order_id,
            "customer": customer,
            "paid_cents": cents,
            "status": status,
        }

    # Validate and index refunds.
    refund_by_order = {}
    for refund_id, order_id, amount in refund_rows:
        cents = _parse_amount_cents(amount, "refund %s" % refund_id)
        order = orders.get(order_id)
        if order is None:
            raise ValueError("refund %s: unknown order %r" % (refund_id, order_id))
        if order["status"] != "paid":
            raise ValueError("refund %s: order %s is not paid" % (refund_id, order_id))
        refund_by_order.setdefault(order_id, 0)
        refund_by_order[order_id] += cents

    order_entries = []
    customers = {}
    totals = {"paid_cents": 0, "refund_cents": 0, "net_cents": 0}

    for order_id in sorted(orders):
        order = orders[order_id]
        if order["status"] != "paid":
            continue
        paid = order["paid_cents"]
        refund = refund_by_order.get(order_id, 0)
        if refund > paid:
            raise ValueError(
                "order %s: refunds %d exceed paid %d" % (order_id, refund, paid)
            )
        net = paid - refund
        order_entries.append(
            {
                "order_id": order_id,
                "customer": order["customer"],
                "paid_cents": paid,
                "refund_cents": refund,
                "net_cents": net,
            }
        )
        customers[order["customer"]] = customers.get(order["customer"], 0) + net
        totals["paid_cents"] += paid
        totals["refund_cents"] += refund
        totals["net_cents"] += net

    customer_entries = [
        {"customer": name, "net_cents": customers[name]} for name in sorted(customers)
    ]

    return {"orders": order_entries, "customers": customer_entries, "totals": totals}


def export_bundle(result):
    return {"summary.json": json.dumps(result, sort_keys=True)}
"}
